const IMG = {
  html: 'data:image/jpeg;base64,',
  banco: 'data:image/jpeg;base64,',
  python: 'data:image/jpeg;base64,',
  git: 'data:image/jpeg;base64,',
  js: 'data:image/jpeg;base64,',
  foto: 'data:image/jpeg;base64,'
};
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const calm = matchMedia('(prefers-reduced-motion: reduce)').matches;

$('.photo img').src = IMG.foto;
const CERTS = [
  { img: IMG.html, title: 'Desenvolvimento de Sistemas Web: CSS e HTML', org: 'FGV Online', h: 15, date: '01/07/2026' },
  { img: IMG.banco, title: 'Banco de Dados 1: fundamentos', org: 'Instituto Federal do Rio Grande do Sul', h: 20, date: '10/11/2026' },
  { img: IMG.python, title: 'Python', org: 'Santander Open Academy', h: 8, date: '10/08/2026' },
  { img: IMG.git, title: 'Git e GitHub', org: 'Cursa', h: 8, date: '04/10/2026' },
  { img: IMG.js, title: 'JavaScript', org: 'Curso em Vídeo', h: 40, date: '22/09/2026' }
];


/* lightbox */
const lb = $('#lb'); let cur = 0;
const show = i => {
  cur = (i + CERTS.length) % CERTS.length;
  const c = CERTS[cur];
  $('#lbImg').src = c.img; $('#lbImg').alt = 'Certificado: ' + c.title;
  $('#lbCap').textContent = `${c.title} · ${c.org} · ${c.h} horas`;
};
const open = i => { show(i); lb.hidden = false; document.body.style.overflow = 'hidden'; $('#lbClose').focus(); };
const close = () => { lb.hidden = true; document.body.style.overflow = ''; };
$$('.chip').forEach(b => b.addEventListener('click', () => open(+b.dataset.cert)));
$('#lbClose').onclick = close;
$('#lbPrev').onclick = () => show(cur - 1);
$('#lbNext').onclick = () => show(cur + 1);
lb.addEventListener('click', e => { if (e.target === lb) close(); });
addEventListener('keydown', e => {
  if (lb.hidden) return;
  if (e.key === 'Escape') close();
  if (e.key === 'ArrowLeft') show(cur - 1);
  if (e.key === 'ArrowRight') show(cur + 1);
});

/* filtro de skills */
$$('.tabs button').forEach(b => b.addEventListener('click', () => {
  $$('.tabs button').forEach(x => x.classList.toggle('on', x === b));
  $$('.card').forEach(c => c.classList.toggle('off', b.dataset.f !== 'all' && c.dataset.g !== b.dataset.f));
}));

/* menu mobile */
const burger = $('#burger'), menu = $('#menu');
burger.onclick = () => { const o = menu.classList.toggle('open'); burger.setAttribute('aria-expanded', o); };
$$('#menu a').forEach(a => a.addEventListener('click', () => { menu.classList.remove('open'); burger.setAttribute('aria-expanded', false); }));

/* progresso + link ativo (sem forçar layout a cada scroll) */
const links = $$('#menu a'), secs = $$('main section[id]'), prog = $('#progress');
let tops = [], docMax = 1, curId = '';
const measure = () => { const h = document.documentElement; docMax = Math.max(1, h.scrollHeight - h.clientHeight); tops = secs.map(x => x.getBoundingClientRect().top + scrollY); };
measure(); addEventListener('resize', measure); addEventListener('load', () => setTimeout(measure, 1300));
if (document.fonts) document.fonts.ready.then(measure);
const updateNav = y => {
  let id = ''; secs.forEach((x, i) => { if (tops[i] - y < innerHeight * .4) id = x.id; });
  if (id !== curId) { curId = id; links.forEach(a => a.classList.toggle('on', a.getAttribute('href') === '#' + id)); }
};


/* inclinação 3D (terminal, foto e certificados) */
const tilt = (el, max) => {
  el.addEventListener('pointermove', e => {
    if (calm || e.pointerType === 'touch') return;
    const r = el.getBoundingClientRect(), x = (e.clientX - r.left) / r.width - .5, y = (e.clientY - r.top) / r.height - .5;
    el.style.transform = `perspective(900px) rotateY(${x * max}deg) rotateX(${-y * max}deg) scale(1.03)`; el.style.setProperty('--gx', (x + .5) * 100 + '%'); el.style.setProperty('--gy', (y + .5) * 100 + '%');
  });
  el.addEventListener('pointerleave', () => el.style.transform = '');
};
tilt($('#terminal'), 14); tilt($('#photo'), 18); $$('.card').forEach(c => tilt(c, 12));

/* texto digitado */
const roles = ['Front-End', 'Web', 'em formação', 'curioso por IA'];
let ri = 0, ci = 0, del = false;
const type = () => {
  const w = roles[ri], t = $('#typing');
  if (calm) { t.textContent = roles[0]; return; }
  t.textContent = w.slice(0, ci += del ? -1 : 1);
  let wait = del ? 45 : 90;
  if (!del && ci === w.length) { del = true; wait = 1400; }
  else if (del && ci === 0) { del = false; ri = (ri + 1) % roles.length; wait = 350; }
  setTimeout(type, wait);
};
type();

/* terminal que se escreve sozinho */
const lines = [
  '<span class="c">// quem sou eu</span>',
  '<span class="k">const</span> caua = {',
  '  nome: <span class="s">"Cauã de Souza Sturaro"</span>,',
  '  foco: <span class="s">"Front-End"</span>,',
  '  stack: [<span class="s">"HTML"</span>, <span class="s">"CSS"</span>, <span class="s">"JS"</span>, <span class="s">"Python"</span>],',
  '  banco: <span class="s">"modelo relacional"</span>,',
  '  git: <span class="s">"GitHub"</span>,',
  '  estudando: <span class="k">true</span>',
  '};'
];
const code = $('#code'); let li = 0;
(function w() { if (li < lines.length) { code.innerHTML += (li ? '\n' : '') + lines[li++]; setTimeout(w, calm ? 0 : 380); } })();

/* contadores */
const io = new IntersectionObserver(es => es.forEach(e => {
  if (!e.isIntersecting) return;
  const b = e.target, to = +b.dataset.to; let n = 0;
  const step = () => { n += Math.max(1, Math.ceil(to / 40)); b.textContent = Math.min(n, to); if (n < to && !calm) requestAnimationFrame(step); else b.textContent = to; };
  step(); io.unobserve(b);
}), { threshold: .6 });
$$('.stats b').forEach(b => io.observe(b));

/* ===== versão 3D ===== */
const L = (a, b, t) => a + (b - a) * t;
const M = { x: innerWidth / 2, y: innerHeight / 2, nx: 0, ny: 0 };
const P = { x: M.x, y: M.y, gx: M.x, gy: M.y, nx: 0, ny: 0, sy: 0 };
const hooks = [];
const ring = $('#ring'), glow = $('#glow'), heroText = $('.hero-text');

let lastT;
addEventListener('pointermove', e => {
  M.x = e.clientX; M.y = e.clientY;
  M.nx = e.clientX / innerWidth * 2 - 1; M.ny = e.clientY / innerHeight * 2 - 1;
  ring.classList.add('on');
  if (e.target !== lastT) { lastT = e.target; ring.classList.toggle('big', !!e.target.closest('a,button,.slide,.card')); }
});

/* galeria 3D de certificados (arrasta acompanhando o dedo/mouse) */
const flow = $('#flow'); let fi = 0;
flow.innerHTML = CERTS.map((c, i) => `<figure class="slide" data-i="${i}"><img src="${c.img}" alt="Certificado: ${c.title}" draggable="false"></figure>`).join('');
const slides = $$('.slide', flow), lastI = CERTS.length - 1;
const place = (p = fi) => {
  slides.forEach((s, i) => {
    const o = i - p, a = Math.abs(o), k = Math.max(-2, Math.min(2, o));
    s.style.transform = `translate(-50%,-50%) translateX(${o * 58}%) translateZ(${-Math.min(a, 3) * 220}px) rotateY(${-k * 38}deg)`;
    s.style.zIndex = 10 - Math.round(a); s.style.opacity = Math.max(0, 1 - a * .28);
    s.classList.toggle('mid', i === Math.round(p));
  });
  const c = CERTS[Math.round(p)];
  if (c) $('#fCap').innerHTML = `<b>${c.title}</b><span>${c.org} · ${c.h} horas</span>`;
};
const go = n => { fi = Math.max(0, Math.min(lastI, n)); flow.classList.remove('drag'); place(); };
$('#fPrev').onclick = () => go(fi - 1);
$('#fNext').onclick = () => go(fi + 1);
let sx = null, dx = 0;
flow.addEventListener('pointerdown', e => { sx = e.clientX; dx = 0; });
addEventListener('pointermove', e => {
  if (sx === null) return;
  dx = e.clientX - sx;
  if (Math.abs(dx) > 6) { flow.classList.add('drag'); place(Math.max(0, Math.min(lastI, fi - dx / 240))); }
});
addEventListener('pointerup', e => {
  if (sx === null) return;
  const moved = Math.abs(dx) > 6; sx = null;
  if (moved) return go(Math.round(fi - dx / 240));
  const s = e.target.closest && e.target.closest('.slide');
  if (s && flow.contains(s)) { const i = +s.dataset.i; i === fi ? open(i) : go(i); }
});
place();

/* botões magnéticos */
$$('.btn').forEach(b => {
  b.addEventListener('pointermove', e => {
    if (calm || e.pointerType === 'touch') return;
    const r = b.getBoundingClientRect();
    b.style.transform = `translate(${(e.clientX - r.left - r.width / 2) * .25}px,${(e.clientY - r.top - r.height / 2) * .35}px)`;
  });
  b.addEventListener('pointerleave', () => b.style.transform = '');
});

/* entrada em 3D ao rolar */
if (!calm) {
  const rv = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return;
    const t = e.target; t.classList.add('in'); rv.unobserve(t);
    setTimeout(() => { t.classList.remove('rv', 'in'); t.style.transitionDelay = ''; }, 1200);
  }), { threshold: .12 });
  $$('.sec h2,.sub,.tabs,.photo,.about-text>*,.card,.flow,.flow-ui,.contact .btn').forEach((el, i) => {
    el.classList.add('rv'); el.style.transitionDelay = (i % 4) * 80 + 'ms'; rv.observe(el);
  });
}

/* cena 3D de fundo: notebook com códigos girando */
(() => {
  const cv = $('#bg'); if (!window.THREE || !cv) return;
  const R = new THREE.WebGLRenderer({ canvas: cv, alpha: true, antialias: true });
  let ratio = Math.min(devicePixelRatio, 1.5), acc = 0, n = 0, lt = 0;
  R.setPixelRatio(ratio);
  const S = new THREE.Scene(), C = new THREE.PerspectiveCamera(55, 1, .1, 100); C.position.z = 7;
  const mats = [], mk = m => { m.transparent = true; mats.push(m); return m; };
  const box = (w, h, d) => {
    const g = new THREE.BoxGeometry(w, h, d);
    const m = new THREE.Mesh(g, mk(new THREE.MeshBasicMaterial({ color: 0x140a0a })));
    m.add(new THREE.LineSegments(new THREE.EdgesGeometry(g), mk(new THREE.LineBasicMaterial({ color: 0xff2b2b }))));
    return m;
  };
  const rig = new THREE.Group(), lap = new THREE.Group(), orbit = new THREE.Group();
  rig.add(lap, orbit); S.add(rig);

  /* base + teclado */
  lap.add(box(3.2, .12, 2.2));
  const kc = document.createElement('canvas'); kc.width = 512; kc.height = 320;
  const kx = kc.getContext('2d');
  kx.fillStyle = '#0b0606'; kx.fillRect(0, 0, 512, 320);
  kx.fillStyle = '#2b1212';
  for (let r = 0; r < 4; r++) for (let c = 0; c < 13; c++) kx.fillRect(14 + c * 37, 14 + r * 40, 31, 34);
  kx.fillRect(100, 174, 300, 34);
  kx.strokeStyle = '#ff2b2b'; kx.lineWidth = 2; kx.strokeRect(190, 230, 132, 76);
  const keys = new THREE.Mesh(new THREE.PlaneGeometry(2.8, 1.75), mk(new THREE.MeshBasicMaterial({ map: new THREE.CanvasTexture(kc) })));
  keys.rotation.x = -Math.PI / 2; keys.position.set(0, .065, .05); lap.add(keys);

  /* tampa + tela com código rolando */
  const lid = new THREE.Group(); lid.position.set(0, .06, -1.1); lid.rotation.x = -.2; lap.add(lid);
  const shell = box(3.2, 2.1, .08); shell.position.y = 1.05; lid.add(shell);
  const cc = document.createElement('canvas'); cc.width = 580; cc.height = 360;
  const cx = cc.getContext('2d'), codeTex = new THREE.CanvasTexture(cc);
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(2.9, 1.8), mk(new THREE.MeshBasicMaterial({ map: codeTex })));
  screen.position.set(0, 1.05, .045); lid.add(screen);
  const SRC = ['// portfólio do Cauã', 'const caua = {', '  nome: "Cauã Sturaro",', '  foco: "Front-End",', '  stack: ["HTML","CSS","JS"],', '};', '', 'function criar(ideia) {', '  return projeto(ideia);', '}', '', '<section class="hero">', '  <h1>Olá, mundo!</h1>', '</section>', '', '.btn:hover {', '  transform: scale(1.05);', '}', '', 'def automatizar():', '    print("Python")', '', 'git commit -m "novo projeto"', 'SELECT * FROM skills;'];
  let off = 0;
  const drawCode = () => {
    cx.fillStyle = '#0b0606'; cx.fillRect(0, 0, 580, 360); cx.font = '15px monospace';
    for (let i = 0; i < 20; i++) {
      const l = SRC[(Math.floor(off) + i) % SRC.length], y = 26 + i * 20 - (off % 1) * 20;
      cx.fillStyle = l.startsWith('//') ? '#7b6a6a' : /const|function|return|def|SELECT|git/.test(l) ? '#ff5a5a' : /^\s*[<.]/.test(l) ? '#ffb4b4' : '#e8dcdc';
      cx.fillText(l, 16, y);
    }
    codeTex.needsUpdate = true;
  };

  /* trechos de código orbitando */
  const WORDS = ['</>', '{ }', '=>', 'const', 'HTML', 'CSS', 'JS', 'Python', 'git', 'SQL', '( )', '<div>'];
  WORDS.forEach((w, i) => {
    const c = document.createElement('canvas'); c.width = 256; c.height = 96;
    const x = c.getContext('2d');
    x.font = 'bold 54px monospace'; x.textAlign = 'center'; x.fillStyle = '#ff4a4a'; x.shadowColor = '#ff2b2b'; x.shadowBlur = 14; x.fillText(w, 128, 64);
    const sp = new THREE.Sprite(mk(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(c) })));
    sp.scale.set(1.1, .41, 1);
    const a = i / WORDS.length * Math.PI * 2;
    sp.position.set(Math.cos(a) * 3.1, Math.sin(i * 1.7) * 1.3 + .4, Math.sin(a) * 3.1);
    orbit.add(sp);
  });

  /* partículas */
  const N = 900, pos = new Float32Array(N * 3);
  for (let i = 0; i < N * 3; i++) pos[i] = (Math.random() - .5) * (i % 3 === 2 ? 12 : 22);
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
  const pts = new THREE.Points(g, new THREE.PointsMaterial({ color: 0xff4040, size: .035, transparent: true, opacity: .7 }));
  S.add(pts);

  const size = () => { R.setSize(innerWidth, innerHeight, false); C.aspect = innerWidth / innerHeight; C.updateProjectionMatrix(); };
  size(); addEventListener('resize', size);
  hooks.push(t => {
    if (lt) { acc += Math.min(t - lt, .05); if (++n === 60) { if (acc / 60 > .021 && ratio > .7) { ratio = Math.max(.7, ratio - .25); R.setPixelRatio(ratio); size(); } acc = 0; n = 0; } } lt = t;
    const w = innerWidth > 850, fade = Math.max(.28, 1 - P.sy / 1600);
    if (Math.abs(fade - (mats.f || 0)) > .005) { mats.f = fade; mats.forEach(m => m.opacity = fade); }
    const fk = Math.floor(t * 30); if (fk !== hooks.fk) { hooks.fk = fk; off = t * 1.5; drawCode(); }
    rig.rotation.y = t * .35 + P.nx * .7 + P.sy * .0012;
    rig.rotation.x = .3 + P.ny * .25;
    orbit.rotation.y = -t * .8;
    rig.position.set(w ? 2.5 * Math.cos(P.sy * .0014) : 0, Math.sin(P.sy * .0014) * 1.2 - .4, 0);
    rig.scale.setScalar((w ? .85 : .6) * (1 + Math.min(P.sy / 2500, .4)));
    pts.rotation.y = t * .03 + P.sy * .0003; pts.rotation.x = P.ny * .1;
    C.position.x = P.nx * .6; C.position.y = -P.ny * .4; C.lookAt(0, 0, 0);
    R.render(S, C);
  });
})();

/* rolagem suave com inércia */
if (!calm && matchMedia('(hover:hover)').matches) {
  document.documentElement.style.scrollBehavior = 'auto';
  let tg = scrollY, cu = scrollY, run = false;
  const max = () => document.documentElement.scrollHeight - innerHeight;
  const step = now => {
    const d = Math.max(0, Math.min(.05, (now - step.t) / 1000)); step.t = now;
    cu = L(cu, tg, 1 - Math.exp(-d * 7)); scrollTo(0, cu);
    if (Math.abs(tg - cu) < .4) { scrollTo(0, tg); run = false; } else requestAnimationFrame(step);
  };
  const start = () => { if (!run) { run = true; cu = scrollY; step.t = performance.now(); requestAnimationFrame(step); } };
  addEventListener('wheel', e => {
    if (e.ctrlKey || !lb.hidden) return;
    e.preventDefault();
    tg = Math.max(0, Math.min(max(), (run ? tg : scrollY) + e.deltaY * (e.deltaMode ? 16 : 1))); start();
  }, { passive: false });
  addEventListener('scroll', () => { if (!run) tg = scrollY; }, { passive: true });
  $$('a[href^="#"]').forEach(a => a.addEventListener('click', e => {
    const id = a.getAttribute('href'), el = $(id); if (!el) return;
    e.preventDefault(); tg = Math.max(0, Math.min(max(), el.getBoundingClientRect().top + scrollY - (id === '#inicio' ? 0 : 72))); start();
  }));
}

/* loop único, com amortecimento independente da taxa de quadros */
const damp = (a, b, k, dt) => a + (b - a) * (1 - Math.exp(-k * dt));
let lastTs = 0, navTick = 0;
const tick = ts => {
  const dt = Math.min(.05, (ts - lastTs) / 1000 || .016); lastTs = ts;
  P.x = damp(P.x, M.x, 18, dt); P.y = damp(P.y, M.y, 18, dt);
  P.gx = damp(P.gx, M.x, 5, dt); P.gy = damp(P.gy, M.y, 5, dt);
  P.nx = damp(P.nx, M.nx, 4, dt); P.ny = damp(P.ny, M.ny, 4, dt);
  const sy = scrollY; P.sy = damp(P.sy, sy, 6, dt);
  glow.style.transform = `translate(${P.gx}px,${P.gy}px) translate(-50%,-50%)`;
  ring.style.transform = `translate(${P.x}px,${P.y}px) translate(-50%,-50%)`;
  prog.style.transform = `scaleX(${sy / docMax})`;
  if (!calm && P.sy < innerHeight) heroText.style.transform = `perspective(1200px) rotateY(${P.nx * 5}deg) rotateX(${-P.ny * 3}deg) translateY(${-P.sy * .12}px)`;
  if (++navTick % 6 === 0) updateNav(sy);
  hooks.forEach(f => f(ts / 1000));
  if (!calm) requestAnimationFrame(tick);
};
requestAnimationFrame(tick);
